package com.automationstudio.engine.karate;
import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;
class DockerWorkerCommandTest {private static final String IMAGE="local/worker:1@sha256:"+"a".repeat(64);private static final String NAME="as-karate-"+"b".repeat(32),NETWORK="as-karate-net-"+"b".repeat(32);
 @Test void configuresIsolationAndExternalResourceLimits(){List<String> c=DockerWorkerCommand.create(NAME,NETWORK,IMAGE,WorkerLimits.defaults());assertTrue(c.contains("--interactive"));assertContains(c,"--network",NETWORK);assertFalse(c.contains("--pid"));assertContains(c,"--read-only","--user");assertContains(c,"--user","10001:10001");assertContains(c,"--cap-drop","ALL");assertContains(c,"--security-opt","no-new-privileges:true");assertContains(c,"--security-opt","seccomp=builtin");assertContains(c,"--pids-limit","128");assertContains(c,"--memory","805306368");assertContains(c,"--cpus","1.0");assertEquals(3,Collections.frequency(c,"--tmpfs"));assertTrue(c.stream().anyMatch(v->v.startsWith("/work/source:rw,noexec,nosuid,nodev,uid=10001,gid=10001,mode=0700,size=")));assertTrue(c.stream().anyMatch(v->v.startsWith("/work/runtime:rw,noexec,nosuid,nodev,uid=10001,gid=10001,mode=0700,size=")));assertTrue(c.stream().anyMatch(v->v.startsWith("/work/tmp:rw,noexec,nosuid,nodev,uid=10001,gid=10001,mode=0700,size=")));assertFalse(c.contains("-v"));assertFalse(c.contains("--volume"));assertFalse(c.stream().anyMatch(v->v.contains("docker.sock")||v.toLowerCase().contains("proxy")));assertEquals(1,Collections.frequency(c,"--env"));assertContains(c,"--env","LANG=C.UTF-8");}
 @Test void requiresDigestPinnedImageAndDeterministicName(){assertThrows(IllegalArgumentException.class,()->DockerWorkerCommand.create(NAME,NETWORK,"local/worker:latest",WorkerLimits.defaults()));assertThrows(IllegalArgumentException.class,()->DockerWorkerCommand.create("bad",NETWORK,IMAGE,WorkerLimits.defaults()));}
 private static void assertContains(List<String> c,String a,String b){assertTrue(java.util.stream.IntStream.range(0,c.size()-1).anyMatch(i->c.get(i).equals(a)&&c.get(i+1).equals(b)));}
}
